<?php declare(strict_types=1);
$priceActor=$settings->actor();if($priceActor['members_access']==='none')return;
$personal=new \Kulturhus\Verein\AssignmentPrices($db,(string)$_SESSION['actor']);$failed=input($_POST,'action')==='assignment-price-save';$source=$failed?$_POST:$_GET;$id=input($source,'price_assignment');$state=null;$context=null;$history=null;$picker=null;$error='';$quote=null;$stale=false;$route=['view'=>'settings','tab'=>$tab,'assignment_prices'=>1];
try{if($id!==''){$context=$personal->context($id);if(($context['catalog']['kind']==='service')!==($tab==='services'))throw new DomainException('Zuweisung im passenden Katalog auswählen.');$state=$personal->get($id);$history=$personal->history($id,(int)input($_GET,'price_history_page','1'));if($failed)$stale=(int)input($_POST,'assignment_price_version')!==(int)($state['version']??0);try{$quote=(new \Kulturhus\Verein\CatalogPricing($db,(string)$_SESSION['actor']))->quote($id,date('Y-m-d'));}catch(DomainException){}}
else $picker=(new \Kulturhus\Verein\CatalogAssignments($db,(string)$_SESSION['actor']))->page($tab,$_GET);}catch(DomainException $e){$error=$e->getMessage();$context=null;}
$mode=input($source,'assignment_price_mode',$state['mode']??'none');$value=input($source,'assignment_price_value',$state&&$state['mode']!=='none'?\Kulturhus\Verein\AssignmentPrices::value($state):'');$version=$failed?(int)input($_POST,'assignment_price_version'):(int)($state['version']??0);$key=input($source,'assignment_price_key',bin2hex(random_bytes(16)));$labels=['none'=>'Tarifpreis','fixed'=>'Persönlicher Festpreis','percent'=>'Prozent-Rabatt'];
?>
<link rel="stylesheet" href="catalog-pricing.css">
<section class="card catalog-pricing assignment-prices" id="assignment-prices"><h2 tabindex="-1" autofocus>Persönlicher Tarifpreis</h2><a class="btn btn-outline theme-secondary" href="<?= e(url(['view'=>'settings','tab'=>$tab])) ?>">Zum Katalog</a>
<?php if($error): ?><p role="alert"><?= e($error) ?></p><?php endif ?>
<?php if($picker): ?><form method="get" class="settings-search"><?= hidden('view','settings').hidden('tab',$tab).hidden('assignment_prices',1) ?><label>Kontakt oder Tarif<input class="form-control" name="pricing_q" value="<?= e($picker['q']) ?>" maxlength="150"></label><button class="btn btn-outline theme-secondary">Suchen</button></form><div class="catalog-assignment-list"><?php foreach($picker['rows']as$row): ?><article class="catalog-assignment"><div><strong><?= e($row['name']) ?></strong><span><?= e($row['catalog_name']) ?></span></div><a class="btn btn-outline theme-secondary" href="<?= e(url($route+['price_assignment'=>$row['id']])) ?>">Persönlichen Preis öffnen</a></article><?php endforeach ?></div><span><?= $picker['total'] ?> Zuweisungen · Seite <?= $picker['page'] ?> von <?= $picker['pages'] ?></span><?php if($picker['pages']>1): ?><form method="get" class="settings-actions"><?= hidden('view','settings').hidden('tab',$tab).hidden('assignment_prices',1).hidden('pricing_q',$picker['q']) ?><label>Zuweisungsseite<input class="form-control" type="number" name="pricing_page" min="1" max="<?= $picker['pages'] ?>" value="<?= $picker['page'] ?>" required></label><button class="btn btn-outline theme-secondary">Seite öffnen</button></form><?php endif ?><?php endif ?>
<?php if($context): ?><article class="catalog-assignment"><div><strong><?= e($context['contact']['name'].' · '.$context['catalog']['data']['name']) ?></strong><small><?= e(dateDe($context['assignment']['starts_on']).' – '.($context['assignment']['ends_on']?dateDe($context['assignment']['ends_on']):'offen')) ?></small><span data-assignment-price-current><?= e($labels[$state['mode']??'none']) ?><?= $state&&$state['mode']!=='none'?e(' · '.($state['mode']==='percent'?str_replace('.',',',\Kulturhus\Verein\AssignmentPrices::value($state)).' %':euro((int)$state['value_units']))):'' ?></span><?php if($quote): ?><strong data-assignment-price-amount><?= e(euro($quote['amount_cents'])) ?> brutto</strong><?php endif ?></div></article>
<?php if($context['linked']): ?><p>Einzel- und Familienjahresbeiträge behalten ihren Tarif.</p><?php elseif($finance->canWrite()&&(int)$context['catalog']['active']): ?>
<?php if($stale): ?><p role="alert">Sonderpreis inzwischen geändert. Aktuellen Stand neu öffnen.</p><?php endif ?>
<form method="post" class="form-grid" data-assignment-price-form><?= csrf().hidden('action','assignment-price-save').hidden('price_assignment',$id).hidden('assignment_price_version',$version).hidden('assignment_price_key',$key) ?><label>Preisart<select class="form-control" name="assignment_price_mode"><?php foreach($labels as$k=>$label): ?><option value="<?= e($k) ?>"<?= $mode===$k?' selected':'' ?>><?= e($label) ?></option><?php endforeach ?></select></label><label>Festpreis brutto (EUR) oder Rabatt (%)<input class="form-control" name="assignment_price_value" value="<?= e($value) ?>" inputmode="decimal" maxlength="30"></label><button class="btn btn-solid theme-primary"<?= $stale?' disabled':'' ?>>Persönlichen Preis speichern</button></form>
<?php endif ?>
<div class="settings-actions"><a class="btn btn-outline theme-secondary" href="<?= e(url(['view'=>'settings','tab'=>$tab,'pricing_assignment'=>$id]).'#catalog-pricing') ?>">Preis &amp; Zeitraum berechnen</a><a class="btn btn-outline theme-secondary" href="<?= e(url($route+['price_assignment'=>$id])) ?>">Aktuellen Stand neu öffnen</a><a class="btn btn-outline theme-secondary" href="<?= e(url($route)) ?>">Andere Zuweisung</a></div>
<?php if($history&&$history['rows']): ?><details><summary>Preisverlauf · <?= $history['total'] ?></summary><div class="catalog-assignment-list" data-assignment-price-history><?php foreach($history['rows']as$row):$original=json_decode($row['state_json'],true,512,JSON_THROW_ON_ERROR); ?><article class="catalog-assignment"><div><strong><?= e($labels[$original['mode']]) ?><?= $original['mode']!=='none'?e(' · '.($original['mode']==='percent'?str_replace('.',',',\Kulturhus\Verein\AssignmentPrices::value($original)).' %':euro((int)$original['value_units']))):'' ?></strong><small><?= e(dateDe(substr($row['created_at'],0,10))) ?> · Version <?= (int)$row['version'] ?></small></div></article><?php endforeach ?></div><?php if($history['pages']>1): ?><form method="get" class="settings-actions"><?= hidden('view','settings').hidden('tab',$tab).hidden('assignment_prices',1).hidden('price_assignment',$id) ?><label>Verlaufsseite<input class="form-control" type="number" name="price_history_page" min="1" max="<?= $history['pages'] ?>" value="<?= $history['page'] ?>" required></label><button class="btn btn-outline theme-secondary">Seite öffnen</button></form><?php endif ?></details><?php endif ?>
<?php endif ?></section>
